"use client";
import { FormEvent, useEffect, useState } from "react";
export default function TeacherSettingsPage() { const [displayName, setDisplayName] = useState(""); const [specialization, setSpecialization] = useState(""); const [bio, setBio] = useState(""); const [message, setMessage] = useState(""); useEffect(() => { void (async () => { const r = await fetch("/api/teacher/profile"); const p = await r.json().catch(() => null); if (r.ok) { setDisplayName(p.data.displayName ?? ""); setSpecialization(p.data.specialization ?? ""); setBio(p.data.bio ?? ""); } })(); }, []); const save = async (event: FormEvent) => { event.preventDefault(); setMessage(""); const r = await fetch("/api/teacher/profile", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ displayName, specialization, bio }) }); const p = await r.json().catch(() => null); setMessage(r.ok ? "Profile saved." : p?.error ?? "Unable to save profile."); }; return <section className="max-w-2xl space-y-6"><header><h2 className="text-3xl font-bold">Teacher profile</h2><p className="mt-2 text-slate-600">Your teaching information is kept separately from the student profile.</p></header><form onSubmit={save} className="space-y-4 rounded-2xl border bg-white p-6"><label className="block font-semibold">Display name<input value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="mt-1 w-full rounded-lg border px-3 py-2"/></label><label className="block font-semibold">Specialization<input value={specialization} onChange={(e) => setSpecialization(e.target.value)} className="mt-1 w-full rounded-lg border px-3 py-2"/></label><label className="block font-semibold">Bio<textarea value={bio} onChange={(e) => setBio(e.target.value)} rows={5} className="mt-1 w-full rounded-lg border p-3"/></label><button className="rounded-lg bg-blue-700 px-4 py-2 font-semibold text-white">Save profile</button>{message ? <p className="text-sm text-slate-700">{message}</p> : null}</form></section>; }
